import java.util.concurrent.CompletableFuture;
import org.eclipse.swt.widgets.Display;
import org.eclipse.swt.widgets.Control; // dummy for setToolTipText

public class MyClass {
    private Control action;

    public MyClass(Control action) {
        this.action = action;
    }

    protected String getToolTip() {
        return "Some Tooltip";
    }

    protected Control getAction() {
        return action;
    }

    protected void updateTooltip() {
        CompletableFuture.supplyAsync(this::getToolTip)
            .thenAccept(tooltip ->
                Display.getDefault().asyncExec(() -> getAction().setToolTipText(tooltip))
            );
    }
}

