import java.util.concurrent.CompletableFuture;
import org.eclipse.swt.widgets.Display;
import org.eclipse.swt.widgets.Control;

public class MyClass {
    private Control action;

    public MyClass(Control action) {
        this.action = action;
    }

    protected String getToolTip() {
        return "Some Tooltip";
    }

    protected Control getAction() {
        return action;
    }

    protected void updateTooltip() {
        // Different executor
        CompletableFuture.supplyAsync(this::getToolTip)
            .thenAcceptAsync(getAction()::setToolTipText, java.util.concurrent.Executors.newSingleThreadExecutor());
    }

    protected void updateTooltip2() {
        // Different action type - not setToolTipText
        CompletableFuture.supplyAsync(this::getToolTip)
            .thenAccept(tooltip ->
                Display.getDefault().asyncExec(() -> System.out.println(tooltip))
            );
    }
}

